import requests
from io import BytesIO

class FileWrapper:
    def __init__(self, data):
        self._data = data
    def __getattr__(self, name):
        if name == 'read':
            return lambda length=-1: self._data.read(length)
        raise AttributeError(name)

def test_getattr_file_wrapper():
    data = BytesIO(b"hello world")
    wrapper = FileWrapper(data)
    # This should be detected as a file and read
    files = {'file': wrapper}
    r = requests.post('http://httpbin.org/post', files=files)
    # Since we don't have a real server, we can just check if _encode_files works
    # But we can't easily call _encode_files because it's a method of PreparedRequest
    # Let's use a mock or just check the logic.
    print("Test executed")

if __name__ == "__main__":
    try:
        test_getattr_file_wrapper()
        print("Success")
    except Exception as e:
